-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.admin_invite_emails(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_by text := public.require_admin_session();
begin
  if jsonb_typeof(p) is distinct from 'object' then
    raise exception 'admin_invite_emails: expected { "emails": [...], "list": "…" }' using errcode = '22023';
  end if;
  return public.invite_emails(jsonb_build_object(
    'emails', p -> 'emails',
    'list', p -> 'list',
    'note', p -> 'note',
    'by', v_by));
end;
$function$;

grant execute on function public.admin_invite_emails(p jsonb) to authenticated;
grant execute on function public.admin_invite_emails(p jsonb) to service_role;
